import { seed } from './seed.mjs';
import { dayKey, createState, normalizeState, updateCard, getStats, timerRemaining, startTimer, pauseTimer, setTimerMode, completeTimer, validateBackup } from './core.mjs';

const KEY='study-station-v1';
const RECOVERY_KEY=KEY+'-recovery';
const subjects=['高等数学','计算机组成','算法','CET-6','通用','其他'];
const icons={sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',cards:'<rect x="5" y="6" width="15" height="15" rx="2"/><path d="M16 3H4a2 2 0 0 0-2 2v12m7-5h7m-7 4h5"/>',book:'<path d="M12 5v16M3 4c4-1 6 0 9 2 3-2 5-3 9-2v15c-4-1-6 0-9 2-3-2-5-3-9-2z"/>',chart:'<path d="M4 3v17h17M8 15V9m5 6V5m5 10v-5"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor" stroke="none"/><circle cx="15" cy="17" r="3" fill="currentColor" stroke="none"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>',flame:'<path d="M13 2c1 5-4 5-3 9 2-1 3-2 3-4 6 5 6 12 0 14-8 1-12-6-7-12 0 3 1 4 2 4-2-5 4-6 5-11z"/>',play:'<path d="m8 5 11 7-11 7z"/>',pause:'<path d="M8 5v14M16 5v14"/>',reset:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7"/>',edit:'<path d="m14 4 6 6M4 20l4-1 12-12a2 2 0 0 0-4-4L4 15z"/>',trash:'<path d="M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',expand:'<path d="M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5"/>',search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',leaf:'<path d="M20 3C7 2 1 9 5 16s16 4 15-13ZM5 20 17 7"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||`id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const $=s=>document.querySelector(s);
const subjectTag=s=>`<span class="subject" data-subject="${esc(s)}">${esc(s)}</span>`;
const subjectOptions=selected=>[...new Set([...subjects,...(selected?[selected]:[])])].map(s=>`<option${s===selected?' selected':''}>${esc(s)}</option>`).join('');
const fmtMinutes=n=>Number.isInteger(n)?String(n):n.toFixed(1);
const fmtTime=s=>`${String(Math.floor(Math.max(0,s)/60)).padStart(2,'0')}:${String(Math.max(0,s)%60).padStart(2,'0')}`;
const shortDate=d=>new Date(d).toLocaleDateString('zh-CN',{month:'numeric',day:'numeric'});
const names={today:'今日计划',cards:'复习卡片',notes:'知识笔记',records:'学习记录'};
let state,storageFailed=false,loadError=false,recoveryRaw=null,recoveryBlocked=false;
let stored=null;
try{stored=localStorage.getItem(KEY);state=stored===null?createState(seed):normalizeState(JSON.parse(stored),seed);}catch{
  state=createState(seed);loadError=true;recoveryRaw=stored;recoveryBlocked=true;
  // Preserve unreadable data before any later automatic save can replace it.
  if(stored!==null){try{localStorage.setItem(RECOVERY_KEY,stored);recoveryBlocked=false;}catch{}}
}
if(recoveryRaw===null){try{recoveryRaw=localStorage.getItem(RECOVERY_KEY);}catch{}}
let view=names[location.hash.slice(1)]?location.hash.slice(1):'today';
let taskFilter='all',cardSubject='全部',cardQuery='',noteQuery='',selectedNote=state.notes[0]?.id||null;
let review=null,noteSaveTimeout,toastTimeout,pendingConfirmation=null,lastDay=dayKey();
const main=$('#main'),dialog=$('#editor-dialog');

function fillIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('visible'),3500);}
function save(){
  if(recoveryBlocked){storageFailed=true;$('#save-status').textContent='原数据受保护，请先导出或导入备份';$('#save-status').classList.add('warning');updateBadge();return false;}
  try{localStorage.setItem(KEY,JSON.stringify(state));storageFailed=false;$('#save-status').innerHTML='<i></i>本地已保存';$('#save-status').classList.remove('warning');updateBadge();return true;}catch{storageFailed=true;$('#save-status').textContent='保存失败，请导出备份';$('#save-status').classList.add('warning');toast('浏览器未能保存，请立即导出备份。');updateBadge();return false;}
}
function updateBadge(){const count=state.cards.filter(c=>c.dueAt<=Date.now()).length;$('#due-badge').textContent=count;}
function todayTasks(){const today=dayKey();return state.tasks.filter(t=>t.dueDate===today||(t.dueDate<today&&(!t.done||(t.completedAt&&dayKey(t.completedAt)===today))));}
function dateLabel(){const date=new Date();return `<div class="date-pill">${icon('calendar')}<strong>${esc(date.toLocaleDateString('zh-CN',{month:'long',day:'numeric'}))}</strong><span>${esc(date.toLocaleDateString('zh-CN',{weekday:'long'}))}</span></div>`;}
function heading(eyebrow,title,description,action=''){return `<div class="heading-row"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="subheading">${description}</p></div>${action||dateLabel()}</div>`;}
function empty(title,description,action=''){return `<div class="empty-state">${icon('leaf')}<strong>${title}</strong><p>${description}</p>${action}</div>`;}
function stat(label,value,unit,foot,ico){return `<article class="stat"><div class="stat-top">${label}${icon(ico)}</div><div class="stat-value">${value}<em>${unit}</em></div><div class="stat-foot">${foot}</div></article>`;}
function weeklyPanel(stats,expanded=false){const max=Math.max(state.settings.dailyGoal,...stats.week.map(w=>w.minutes),1);const sum=stats.week.reduce((a,w)=>a+w.minutes,0);return `<section class="panel weekly-panel"><div class="panel-heading"><h2>最近七天<span class="section-caption">积累，看得见</span></h2><span class="count-label">${esc(shortDate(stats.week[0].date+'T12:00:00'))} — ${esc(shortDate(stats.week[6].date+'T12:00:00'))}</span></div><div class="weekly-body"><div class="week-summary"><strong>${fmtMinutes(sum)}</strong><span> 分钟</span><p>每天一点点，<br>慢慢走得很远。</p></div><div class="week-chart" role="img" aria-label="${esc(stats.week.map(w=>w.date+'：'+fmtMinutes(w.minutes)+' 分钟').join('；'))}">${stats.week.map(w=>`<div class="week-column ${w.date===dayKey()?'today':''}"><span class="week-number">${w.minutes?fmtMinutes(w.minutes):''}</span><div class="week-bar" style="height:${Math.max(3,Math.round(w.minutes/max*(expanded?100:75)))}px"></div><small>${w.date===dayKey()?'今天':esc(new Date(w.date+'T12:00:00').toLocaleDateString('zh-CN',{weekday:'narrow'}))}</small></div>`).join('')}</div></div></section>`;}
function taskRow(t){return `<div class="task-row ${t.done?'done':''}"><input class="check-task" type="checkbox" data-task-toggle="${esc(t.id)}" aria-label="${esc((t.done?'标记未完成：':'完成：')+t.title)}" ${t.done?'checked':''}><div class="task-main"><div class="task-title">${esc(t.title)}</div><div class="task-meta">${subjectTag(t.subject)}<span>${esc(t.minutes)} 分钟</span>${t.dueDate<dayKey()?`<span>${esc(t.dueDate.slice(5))}${t.done?' 已完成':' 待完成'}</span>`:''}</div></div><div class="task-actions">${!t.done?`<button class="icon-button timer-action" data-action="focus-task" data-id="${esc(t.id)}" aria-label="${esc('专注：'+t.title)}" title="专注这项任务">${icon('play')}</button>`:''}<button class="icon-button" data-action="edit-task" data-id="${esc(t.id)}" aria-label="${esc('编辑：'+t.title)}">${icon('edit')}</button><button class="icon-button danger" data-action="delete-task" data-id="${esc(t.id)}" aria-label="${esc('删除：'+t.title)}">${icon('trash')}</button></div></div>`;}
function renderToday(){const stats=getStats(state);const tasks=todayTasks();const done=tasks.filter(t=>t.done).length;const filtered=tasks.filter(t=>taskFilter==='all'||(taskFilter==='done'?t.done:!t.done));return `${heading('MAKE ROOM FOR WHAT MATTERS','把今天，学扎实。','不必一次走很远。选一件事，认真地开始。')}<div class="stats">${stat('今日专注',fmtMinutes(stats.todayMinutes),'分钟',`目标 ${state.settings.dailyGoal} 分钟 · ${Math.min(100,Math.round(stats.todayMinutes/state.settings.dailyGoal*100))}%`,'clock')}${stat('已完成任务',done,`/ ${tasks.length}`,done?'每一次完成，都是积累':'从一个小目标开始','check')}${stat('待复习卡片',stats.dueCards,'张','回忆一次，让知识更牢一点','cards')}${stat('连续学习',stats.streak,'天',stats.streak?'保持你的学习节奏':'完成一次专注，点亮今天','flame')}</div><div class="today-grid"><div class="left-stack"><section class="panel"><div class="panel-heading"><h2>今天要做<span class="section-caption">小目标，大进展</span></h2><button class="button" data-action="new-task">${icon('plus')}添加任务</button></div><div class="task-toolbar">${[['all','全部'],['todo','未完成'],['done','已完成']].map(([id,label])=>`<button class="chip ${taskFilter===id?'active':''}" aria-pressed="${taskFilter===id}" data-action="task-filter" data-filter="${id}">${label}</button>`).join('')}</div><div class="task-list">${filtered.length?filtered.map(taskRow).join(''):empty('这里暂时没有任务',taskFilter==='done'?'完成的任务会出现在这里。':'给今天安排一个可以完成的小目标。')}</div><div class="task-bottom"><span>${done} / ${tasks.length} 项已完成${state.tasks.some(t=>t.dueDate>dayKey())?` · ${state.tasks.filter(t=>t.dueDate>dayKey()).length} 项未来计划`:''}</span><div class="progress-track"><span style="width:${tasks.length?done/tasks.length*100:0}%"></span></div></div></section>${state.tasks.some(t=>t.dueDate>dayKey())?`<section class="panel"><div class="panel-heading"><h2>接下来的安排</h2></div><div class="task-list">${state.tasks.filter(t=>t.dueDate>dayKey()).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).map(t=>taskRow(t).replace(`${t.minutes} 分钟`,`${t.minutes} 分钟 · ${esc(t.dueDate.slice(5))}`)).join('')}</div></section>`:''}${weeklyPanel(stats)}</div><div class="right-stack">${timerPanel()}<aside class="review-nudge"><span class="eyebrow">A LITTLE RECALL, EVERY DAY</span><h3>让学过的，留下来。</h3><p>${stats.dueCards?`今天有 ${stats.dueCards} 张卡片等你温习。`:'今天的到期卡片都复习完了。'}<br>先试着回忆，再翻开答案。</p><button class="text-button" data-action="go-cards">去复习卡片 ${icon('arrow')}</button></aside></div></div><p class="intro-note" style="margin-top:19px">起步任务与卡片均为可编辑示例；学习统计从你实际完成的专注开始记录。</p>`;}
function timerPanel(){return `<section class="panel timer-panel"><div class="timer-header"><span>留一段时间给专注</span>${icon('leaf')}</div><div class="mode-tabs" role="group" aria-label="计时模式"><button data-action="timer-mode" data-mode="focus" class="${state.timer.mode==='focus'?'active':''}" aria-pressed="${state.timer.mode==='focus'}">专注</button><button data-action="timer-mode" data-mode="break" class="${state.timer.mode==='break'?'active':''}" aria-pressed="${state.timer.mode==='break'}">休息</button></div><div class="timer-ring" id="timer-ring"><div class="timer-inner"><div class="timer-digits" id="timer-digits" role="timer" aria-label="剩余时间">${fmtTime(timerRemaining(state.timer))}</div><span class="timer-state" id="timer-state">准备开始</span></div></div><label class="screen-reader" for="timer-task">关联学习任务</label><select id="timer-task" ${state.timer.status==='running'?'disabled':''}><option value="">自由专注，不关联任务</option>${state.tasks.filter(t=>!t.done||t.id===state.timer.taskId).map(t=>`<option value="${esc(t.id)}" ${t.id===state.timer.taskId?'selected':''}>${esc(t.title)}</option>`).join('')}</select><div class="timer-buttons"><button class="primary" id="timer-toggle" data-action="timer-toggle">${icon('play')}开始专注</button><button class="button" data-action="timer-reset" aria-label="重置计时器">${icon('reset')}</button></div><div class="timer-bottom"><span id="timer-duration">${state.settings.focusMinutes} 分钟专注 / ${state.settings.breakMinutes} 分钟休息</span><button class="text-button" data-action="immersive">${icon('expand')}沉浸</button></div><p class="timer-note">完整完成后记入统计；提前重置不计入。<br>离开页面后仍按实际经过时间计时。</p></section>`;}
function filteredCards(){return state.cards.filter(c=>(cardSubject==='全部'||c.subject===cardSubject)&&(!cardQuery||`${c.front} ${c.back} ${c.tags?.join(' ')}`.toLocaleLowerCase().includes(cardQuery.toLocaleLowerCase())));}
function renderCards(){if(review)return renderReview();const cards=filteredCards(),due=cards.filter(c=>c.dueAt<=Date.now());return `${heading('RECALL. REPEAT. REMEMBER.','学过，也要记得。','先主动回忆，再核对答案。给知识一点重复的时间。',`<button class="primary" data-action="new-card">${icon('plus')}新建卡片</button>`)}<div class="card-summary"><div><h2>${due.length?`今天，温习 ${due.length} 张卡片。`:'这一轮，已经温习好了。'}</h2><p>按当前筛选安排复习 · 简易间隔排期，可随时调整卡片内容</p></div><button class="primary" data-action="start-review" ${due.length?'':'disabled'}>${icon('play')}开始今日复习</button></div><div class="toolbar"><div class="filter-row" role="group" aria-label="卡片学科">${['全部',...subjects].map(s=>`<button class="chip ${cardSubject===s?'active':''}" data-action="card-subject" data-subject="${s}" aria-pressed="${cardSubject===s}">${s}</button>`).join('')}</div><label class="search">${icon('search')}<input type="search" id="card-search" value="${esc(cardQuery)}" placeholder="搜索问题、答案或标签" aria-label="搜索复习卡片"></label></div><p class="intro-note">${cards.length} 张卡片 · ${due.length} 张到期。初始卡片为示例，可编辑、删除或添加自己的知识。</p><div class="card-grid">${cards.length?cards.map(c=>`<article class="study-card"><div class="study-card-header">${subjectTag(c.subject)}<span class="due-label">${c.dueAt<=Date.now()?'待复习':esc(shortDate(c.dueAt))+' 复习'}</span></div><h3>${esc(c.front)}</h3><div class="tag-list">${(c.tags||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="study-card-footer"><button class="text-button" data-action="preview-card" data-id="${esc(c.id)}">翻开看看 ${icon('arrow')}</button><span><button class="icon-button" data-action="edit-card" data-id="${esc(c.id)}" aria-label="${esc('编辑卡片：'+c.front)}">${icon('edit')}</button><button class="icon-button danger" data-action="delete-card" data-id="${esc(c.id)}" aria-label="${esc('删除卡片：'+c.front)}">${icon('trash')}</button></span></div></article>`).join(''):empty('没有找到卡片','换一个关键词，或新建你自己的卡片。')}</div>`;}
function renderReview(){if(!review.ids.length){return `${heading('WELL DONE','这一轮，完成了。','让知识慢慢变熟悉。')}<div class="review-complete">${icon('leaf')}<h2>把一点进步，留给明天。</h2><p>本轮完成 ${review.completed} 张卡片。下次复习时间已经保存。</p><button class="primary" data-action="end-review">返回卡片库</button></div>`;}const c=state.cards.find(c=>c.id===review.ids[0]);if(!c){review.ids.shift();return renderReview();}const intervals=['again','hard','good','easy'].map(r=>updateCard(c,r));return `${heading(review.practice?'A MOMENT OF RECALL':'ONE CARD AT A TIME',review.practice?'翻一张卡，想一想。':'一点点，记得更牢。','先试着说出答案，再翻开卡片。',`<button class="button" data-action="end-review">${icon('close')}结束本轮</button>`)}<div class="review-stage"><div class="review-top"><span>第 ${review.completed+1} / ${review.total} 张</span><span>${review.practice?'自由复习':'到期复习'} · ${review.completed} 张已完成</span></div><div class="review-paper">${subjectTag(c.subject)}<h2>${esc(c.front)}</h2>${review.revealed?`<div class="card-answer">${esc(c.back)}</div><span class="count-label">根据回忆的情况，选择下一次复习时间。</span>`:`<button class="primary" data-action="reveal-card">显示答案</button>`}</div>${review.revealed?`<div class="rating-row">${[['again','还没记住'],['hard','有点吃力'],['good','记得清楚'],['easy','很轻松']].map(([r,label],i)=>`<button data-action="rate-card" data-rating="${r}">${label}<small>${i===0?'约 1 分钟后':`约 ${fmtMinutes(intervals[i].intervalDays)} 天后`}</small></button>`).join('')}</div>`:''}</div>`;}
function renderNotes(){const notes=state.notes.filter(n=>`${n.title} ${n.body}`.toLocaleLowerCase().includes(noteQuery.toLocaleLowerCase())).sort((a,b)=>b.updatedAt-a.updatedAt);const current=state.notes.find(n=>n.id===selectedNote);return `${heading('TURN EXPERIENCE INTO UNDERSTANDING','写下来，想明白。','记下卡住的地方，也记下终于想通的那一刻。',`<button class="primary" data-action="new-note">${icon('plus')}新建笔记</button>`)}<div class="toolbar"><label class="search">${icon('search')}<input type="search" id="note-search" value="${esc(noteQuery)}" placeholder="搜索笔记标题和内容" aria-label="搜索笔记"></label><span class="count-label">${state.notes.length} 则笔记 · 编辑后自动保存</span></div><div class="notes-layout"><div class="notes-list">${notes.map(n=>`<button class="note-preview ${n.id===selectedNote?'active':''}" data-action="select-note" data-id="${esc(n.id)}" aria-pressed="${n.id===selectedNote}"><h3>${esc(n.title)}</h3>${subjectTag(n.subject)}<p>${esc(n.body.slice(0,95))}</p></button>`).join('')||empty('没有找到笔记','记录自己的第一则学习笔记。')}<button class="new-note-button" data-action="new-note">＋ 新建一则笔记</button></div>${current?`<section class="panel note-editor"><label class="screen-reader" for="note-title">笔记标题</label><input id="note-title" name="title" maxlength="150" value="${esc(current.title)}" placeholder="给这则笔记一个标题"><div class="note-select-row"><label class="screen-reader" for="note-subject">笔记学科</label><select id="note-subject">${subjectOptions(current.subject)}</select><span id="note-save-status">${current.updatedAt?'更新于 '+esc(new Date(current.updatedAt).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})):'示例笔记，可自由修改'}</span></div><label class="screen-reader" for="note-body">笔记正文</label><textarea id="note-body" maxlength="30000" placeholder="原题 / 当时的想法 / 卡住的原因 / 正确思路 / 下次如何识别……">${esc(current.body)}</textarea><div class="editor-actions"><button class="text-button push-left" data-action="note-to-card">${icon('cards')}提炼成复习卡</button><button class="icon-button danger" data-action="delete-note" data-id="${esc(current.id)}" aria-label="删除当前笔记">${icon('trash')}</button><button class="secondary" data-action="save-note">${icon('check')}保存笔记</button></div></section>`:`<section class="panel">${empty('留一个位置给思考','点击左侧笔记开始编辑，或创建一则新的笔记。')}</section>`}</div>`;}
function renderRecords(){const stats=getStats(state);const totalBySubject=Object.create(null);state.sessions.forEach(s=>{const sub=s.subject||state.tasks.find(t=>t.id===s.taskId)?.subject||'自由专注';totalBySubject[sub]=(totalBySubject[sub]||0)+s.minutes;});const max=Math.max(...Object.values(totalBySubject),1);return `${heading('YOUR EFFORT LEAVES A TRACE','每一步，都算数。','这里记录你真正完成的专注。没有比较，只有自己的节奏。')}<div class="stats">${stat('累计专注',fmtMinutes(stats.totalMinutes),'分钟','由完整完成的专注计时累积','clock')}${stat('完成专注',stats.totalSessions,'次','休息时间不计入专注统计','check')}${stat('累计复习',stats.totalReviews,'次','每次评价一张卡片，计为一次','cards')}${stat('连续学习',stats.streak,'天','按本地日期统计专注记录','flame')}</div><div class="record-layout">${weeklyPanel(stats,true)}<section class="panel"><div class="panel-heading"><h2>专注分配</h2><span class="count-label">累计时间</span></div>${Object.keys(totalBySubject).length?`<div class="subject-breakdown">${Object.entries(totalBySubject).sort((a,b)=>b[1]-a[1]).map(([s,m])=>`<div class="breakdown-row"><span>${esc(s)}</span><div class="progress-track"><span style="width:${m/max*100}%"></span></div><span>${fmtMinutes(m)} 分</span></div>`).join('')}</div>`:empty('还没有专注记录','在今日计划里完成一次专注，记录会自动出现。')}</section><section class="panel"><div class="panel-heading"><h2>最近的专注</h2><span class="count-label">最近 20 次</span></div><div class="record-list">${[...state.sessions].sort((a,b)=>b.endedAt-a.endedAt).slice(0,20).map(s=>`<div class="record-row"><div><p>${esc(s.title||state.tasks.find(t=>t.id===s.taskId)?.title||'自由专注')}</p><small>${esc(new Date(s.endedAt).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}))}</small></div><span class="record-minutes">${fmtMinutes(s.minutes)} <small>分</small></span></div>`).join('')||empty('从下一次开始积累','完整完成计时后，才会写入学习记录。')}</div></section></div>`;}
function render(){clearTimeout(noteSaveTimeout);document.title=`${names[view]} · 自习站`;$('#view-name').textContent=names[view];document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});main.innerHTML=view==='today'?renderToday():view==='cards'?renderCards():view==='notes'?renderNotes():renderRecords();updateBadge();updateTimerUI();}
function navigate(next){flushNote();review=null;view=next;if(location.hash!==`#${next}`)location.hash=next;else render();}
function dialogHead(title){return `<div class="dialog-heading"><h2 id="dialog-title">${title}</h2><button type="button" class="icon-button" data-action="close-dialog" aria-label="关闭对话框">${icon('close')}</button></div>`;}
function openDialog(html){$('#editor-content').innerHTML=html;dialog.showModal();}
function openTask(id){const t=state.tasks.find(t=>t.id===id);openDialog(`${dialogHead(t?'编辑任务':'给今天一个小目标')}<form id="task-form" data-id="${esc(id||'')}"><label class="field">任务名称<input name="title" required maxlength="200" value="${esc(t?.title||'')}" placeholder="例如：完成罗尔定理的三道例题" autofocus></label><div class="field-row"><label class="field">学科<select name="subject">${subjectOptions(t?.subject||'高等数学')}</select></label><label class="field">计划专注（分钟）<input type="number" name="minutes" min="1" max="180" step="1" value="${t?.minutes||25}" required></label></div><label class="field">安排日期<input type="date" name="dueDate" value="${esc(t?.dueDate||dayKey())}" required min="2000-01-01" max="2100-12-31"></label><p class="form-hint">任务关联计时后，完成专注会自动记入学习记录。任务完成状态由你勾选。</p><div class="editor-actions"><button type="button" class="button" data-action="close-dialog">取消</button><button type="submit" class="primary">保存任务</button></div></form>`);}
function openCard(id,prefill={}){const c=state.cards.find(c=>c.id===id)||prefill;openDialog(`${dialogHead(id?'编辑复习卡':'把一个知识点装进卡片')}<form id="card-form" data-id="${esc(id||'')}"><label class="field">学科<select name="subject">${subjectOptions(c.subject||'高等数学')}</select></label><label class="field">问题 / 提示<textarea name="front" required maxlength="2000" placeholder="一张卡片，只问一个问题。" autofocus>${esc(c.front||'')}</textarea></label><label class="field">答案 / 关键解释<textarea name="back" required maxlength="10000" placeholder="用自己的话，写出准确的答案。">${esc(c.back||'')}</textarea></label><label class="field">标签（用逗号分开）<input name="tags" maxlength="250" value="${esc((c.tags||[]).join('，'))}" placeholder="例如：导数，定理条件"></label><p class="form-hint">新卡片立即进入待复习列表。编辑卡片保留已有复习排期。</p><div class="editor-actions"><button type="button" class="button" data-action="close-dialog">取消</button><button type="submit" class="primary">保存卡片</button></div></form>`);}
function confirmAction(title,body,fn,buttonText='确认删除'){pendingConfirmation=fn;openDialog(`${dialogHead(esc(title))}<div class="confirm-body">${esc(body)}</div><div class="editor-actions"><button class="button" data-action="close-dialog">取消</button><button class="danger-button" data-action="confirm">${esc(buttonText)}</button></div>`);}
function openSettings(){openDialog(`${dialogHead('按自己的节奏来')}<form id="settings-form"><div class="field-row triple"><label class="field">专注 / 分钟<input type="number" name="focusMinutes" min="1" max="180" step="1" required value="${state.settings.focusMinutes}"></label><label class="field">休息 / 分钟<input type="number" name="breakMinutes" min="1" max="60" step="1" required value="${state.settings.breakMinutes}"></label><label class="field">每日目标 / 分钟<input type="number" name="dailyGoal" min="5" max="1440" step="1" required value="${state.settings.dailyGoal}"></label></div><p class="form-hint">时长修改将在下一次新计时生效，正在进行的计时保持原计划。</p><div class="editor-actions"><button type="submit" class="primary">保存偏好</button></div></form><section class="settings-section"><h3>把学习带在身边</h3><p>数据仅保存在当前浏览器，清理网站数据或更换设备会使它不可见。导出 JSON 备份，再在另一台设备导入即可。在线版与离线版的数据分别保存。</p><div class="settings-buttons"><button class="button" data-action="export">${icon('download')}导出备份</button><button class="button" data-action="import">${icon('upload')}导入备份</button><button class="button" data-action="paste-import">粘贴备份</button></div><p class="form-hint">导入会替换当前全部学习数据。建议先导出当前备份；支持最大 5 MB 的自习站 JSON 文件。</p>${recoveryBlocked?'<p class="error-message">为保护未读取的原有数据，当前编辑不会覆盖本地存储。请先导出当前内容，再导入有效备份以恢复保存。</p>':''}${recoveryRaw!==null?`<p class="form-hint">原有数据曾无法读取，原始内容已保留供恢复。</p><button class="button" data-action="download-recovery">${icon('download')}下载未读取的原始数据</button>`:''}</section>`);}
function flushNote(){clearTimeout(noteSaveTimeout);if(view!=='notes'||!$('#note-title'))return;const n=state.notes.find(n=>n.id===selectedNote);if(!n)return;const title=$('#note-title').value.trim()||'未命名笔记',body=$('#note-body').value,subject=$('#note-subject').value;if(n.title!==title||n.body!==body||n.subject!==subject){Object.assign(n,{title,body,subject,updatedAt:Date.now()});save();}if($('#note-save-status'))$('#note-save-status').textContent=storageFailed?'保存失败，请导出备份':'已保存';}
function updateTimerUI(){const remaining=timerRemaining(state.timer);const mode=state.timer.mode;const running=state.timer.status==='running';const paused=state.timer.status==='paused';const title=running?'暂停':paused?'继续':mode==='focus'?'开始专注':'开始休息';const total=state.timer.durationSeconds||((mode==='focus'?state.settings.focusMinutes:state.settings.breakMinutes)*60);const degrees=Math.max(0,Math.min(360,(1-remaining/total)*360));if($('#timer-digits')){$('#timer-digits').textContent=fmtTime(remaining);$('#timer-ring').style.background=`conic-gradient(#80936e ${degrees}deg,#d5dcc9 ${degrees}deg)`;$('#timer-state').textContent=running?(mode==='focus'?'正在专注':'放松一下'):paused?'已暂停':'准备开始';$('#timer-toggle').innerHTML=icon(running?'pause':'play')+title;$('#timer-task').disabled=running;$('#timer-duration').textContent=mode==='focus'?`${fmtMinutes(total/60)} 分钟专注 / ${state.settings.breakMinutes} 分钟休息`:`${state.settings.focusMinutes} 分钟默认专注 / ${fmtMinutes(total/60)} 分钟休息`;}$('#focus-time').textContent=fmtTime(remaining);$('#focus-toggle').textContent=title;$('#focus-task').textContent=mode==='break'?'深呼吸，给自己一点空白。':state.tasks.find(t=>t.id===state.timer.taskId)?.title||'自由专注，享受心无旁骛的片刻。';}
function settleExpiredTimer(now=Date.now()){
  if(state.timer.status!=='running'||timerRemaining(state.timer,now)>0)return false;
  flushNote();const mode=state.timer.mode;state=completeTimer(state,now);save();
  if(!dialog.open)render();else updateTimerUI();
  toast(mode==='focus'?'这段专注完成了。休息一下，再继续。':'休息结束，准备好再开始下一段。');return true;
}
function toggleTimer(){const now=Date.now();if(settleExpiredTimer(now))return;state.timer=state.timer.status==='running'?pauseTimer(state.timer,now):startTimer(state.timer,now);save();updateTimerUI();}
function resetTimer(){settleExpiredTimer();const taskId=state.timer.taskId;state.timer=setTimerMode(state.timer,state.timer.mode,state.settings);state.timer.taskId=taskId;save();updateTimerUI();}
function startReview(ids,practice=false){if(!ids.length){toast('当前没有到期卡片。');return;}review={ids:[...ids],total:ids.length,completed:0,revealed:false,practice};render();}
function backup(){flushNote();const blob=new Blob([JSON.stringify({app:'study-station',version:1,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`自习站备份-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('备份已导出，请妥善保存。');}
function downloadRecovery(){if(recoveryRaw===null)return;const url=URL.createObjectURL(new Blob([recoveryRaw],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`自习站未读取的原始数据-${dayKey()}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('原始数据已下载，请保留用于恢复。');}
function openPasteBackup(){dialog.close();openDialog(`${dialogHead('粘贴备份')}<form id="backup-paste-form"><label class="field">备份 JSON 内容<textarea name="backup" id="backup-paste-content" required maxlength="5242880" aria-describedby="backup-paste-error" placeholder="粘贴自习站导出的完整 JSON 备份内容" autofocus></textarea></label><p class="form-hint">检查通过后，会显示数据数量并再次确认替换。</p><p id="backup-paste-error" class="error-message" role="alert"></p><div class="editor-actions"><button type="button" class="button" data-action="close-dialog">取消</button><button type="submit" class="primary">检查并导入</button></div></form>`);}
function offerImport(imported){dialog.close();confirmAction('用备份替换当前数据？',`将导入 ${imported.tasks.length} 项任务、${imported.cards.length} 张卡片、${imported.notes.length} 则笔记和 ${imported.sessions.length} 条专注记录。当前数据会被替换，建议先取消并导出备份。`,()=>{flushNote();recoveryBlocked=false;loadError=false;state=completeTimer(imported,Date.now());if(state.timer.status==='running')state.timer=pauseTimer(state.timer);selectedNote=state.notes[0]?.id||null;review=null;const saved=save();render();toast(saved?'备份已导入。':'备份已导入，但未能保存，请立即导出备份。');},'确认替换');}
function handleAction(action,button){const id=button.dataset.id;if(['timer-mode','focus-task'].includes(action))settleExpiredTimer();if(action==='new-task')openTask();else if(action==='edit-task')openTask(id);else if(action==='delete-task'){const t=state.tasks.find(t=>t.id===id);if(t)confirmAction('删除这项任务？',t.title,()=>{state.tasks=state.tasks.filter(t=>t.id!==id);if(state.timer.taskId===id)state.timer.taskId=null;save();render();toast('任务已删除。');});}else if(action==='task-filter'){taskFilter=button.dataset.filter;render();}else if(action==='timer-toggle')toggleTimer();else if(action==='timer-reset')resetTimer();else if(action==='timer-mode'){state.timer=setTimerMode(state.timer,button.dataset.mode,state.settings);save();render();}else if(action==='immersive'){$('#focus-dialog').showModal();updateTimerUI();}else if(action==='focus-task'){const t=state.tasks.find(t=>t.id===id);if(!t)return;const begin=()=>{settleExpiredTimer();state.timer=setTimerMode(state.timer,'focus',{...state.settings,focusMinutes:t.minutes});state.timer.taskId=id;state.timer=startTimer(state.timer);save();render();toast(`开始专注：${t.title}`);};if(state.timer.status!=='idle')confirmAction('开始新的专注？','当前计时会被重置，未完成的这一段不计入统计。',begin,'开始新的专注');else begin();}else if(action==='go-cards')navigate('cards');else if(action==='new-card')openCard();else if(action==='edit-card')openCard(id);else if(action==='delete-card'){const c=state.cards.find(c=>c.id===id);if(c)confirmAction('删除这张卡片？',c.front,()=>{state.cards=state.cards.filter(c=>c.id!==id);save();render();toast('卡片已删除。');});}else if(action==='card-subject'){cardSubject=button.dataset.subject;render();}else if(action==='start-review')startReview(filteredCards().filter(c=>c.dueAt<=Date.now()).map(c=>c.id));else if(action==='preview-card')startReview([id],true);else if(action==='end-review'){review=null;render();}else if(action==='reveal-card'){review.revealed=true;render();}else if(action==='rate-card'){if(!review?.revealed)return;const c=state.cards.find(c=>c.id===review.ids[0]);state.cards=state.cards.map(x=>x.id===c.id?updateCard(c,button.dataset.rating):x);review.ids.shift();review.completed++;review.revealed=false;save();render();}else if(action==='new-note'){flushNote();const note={id:uid(),title:'未命名笔记',subject:'高等数学',body:'',createdAt:Date.now(),updatedAt:Date.now()};state.notes.unshift(note);selectedNote=note.id;noteQuery='';save();render();$('#note-title')?.focus();$('#note-title')?.select();}else if(action==='select-note'){flushNote();selectedNote=id;render();}else if(action==='save-note'){flushNote();render();toast('笔记已保存。');}else if(action==='delete-note'){flushNote();const n=state.notes.find(n=>n.id===id);if(n)confirmAction('删除这则笔记？',n.title,()=>{state.notes=state.notes.filter(n=>n.id!==id);selectedNote=state.notes[0]?.id||null;save();render();toast('笔记已删除。');});}else if(action==='note-to-card'){flushNote();const n=state.notes.find(n=>n.id===selectedNote);if(n)openCard(null,{subject:n.subject,front:n.title,back:n.body});}else if(action==='close-dialog'){dialog.close();pendingConfirmation=null;}else if(action==='confirm'){const fn=pendingConfirmation;pendingConfirmation=null;dialog.close();fn?.();}else if(action==='export')backup();else if(action==='download-recovery')downloadRecovery();else if(action==='paste-import')openPasteBackup();else if(action==='import')$('#import-file').click();}
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(button&&!button.disabled)handleAction(button.dataset.action,button);});
document.addEventListener('change',e=>{if(e.target.matches('[data-task-toggle]')){const t=state.tasks.find(t=>t.id===e.target.dataset.taskToggle);if(t){t.done=e.target.checked;t.completedAt=t.done?Date.now():null;save();render();}}else if(e.target.id==='timer-task'){const taskId=e.target.value||null;if(state.timer.status==='idle'&&state.timer.mode==='focus'){const task=state.tasks.find(t=>t.id===taskId);state.timer=setTimerMode(state.timer,'focus',{...state.settings,focusMinutes:task?.minutes??state.settings.focusMinutes});}state.timer.taskId=taskId;save();updateTimerUI();}else if(e.target.id==='note-subject')flushNote();});
document.addEventListener('input',e=>{if(e.target.id==='card-search'){cardQuery=e.target.value;const pos=e.target.selectionStart;render();const input=$('#card-search');input.focus();if(input.type!=='search')input.setSelectionRange(pos,pos);}else if(e.target.id==='note-search'){flushNote();noteQuery=e.target.value;render();$('#note-search').focus();}else if(['note-title','note-body'].includes(e.target.id)){$('#note-save-status').textContent='正在编辑…';clearTimeout(noteSaveTimeout);noteSaveTimeout=setTimeout(flushNote,500);}});
document.addEventListener('submit',e=>{if(e.target.id==='backup-paste-form'){e.preventDefault();const input=$('#backup-paste-content');try{offerImport(validateBackup(input.value,seed));}catch(error){$('#backup-paste-error').textContent=`无法导入：${error.message||'文件格式不正确'}`;input.setAttribute('aria-invalid','true');input.focus();}return;}if(!['task-form','card-form','settings-form'].includes(e.target.id))return;e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form));if(form.id==='task-form'){const title=values.title.trim();if(!title){toast('请填写任务名称。');return;}const task=state.tasks.find(t=>t.id===form.dataset.id);const data={title,subject:values.subject,minutes:Number(values.minutes),dueDate:values.dueDate};if(task)Object.assign(task,data);else state.tasks.push({id:uid(),...data,done:false,completedAt:null,createdAt:Date.now()});}else if(form.id==='card-form'){if(!values.front.trim()||!values.back.trim()){toast('问题和答案都需要填写。');return;}const card=state.cards.find(c=>c.id===form.dataset.id);const data={subject:values.subject,front:values.front.trim(),back:values.back.trim(),tags:values.tags.split(/[,，]/).map(t=>t.trim()).filter(Boolean).slice(0,12)};if(card)Object.assign(card,data);else state.cards.unshift({id:uid(),...data,dueAt:Date.now(),intervalDays:0,reviews:0,lastReviewed:null});}else{state.settings={focusMinutes:Number(values.focusMinutes),breakMinutes:Number(values.breakMinutes),dailyGoal:Number(values.dailyGoal)};if(state.timer.status==='idle'){const taskId=state.timer.taskId;state.timer=setTimerMode(state.timer,state.timer.mode,state.settings);state.timer.taskId=taskId;}}save();dialog.close();render();toast('已保存。');});
$('#settings-button').addEventListener('click',()=>{flushNote();openSettings();});$('#quick-settings').addEventListener('click',()=>{flushNote();openSettings();});$('#exit-focus').addEventListener('click',()=>$('#focus-dialog').close());$('#focus-toggle').addEventListener('click',toggleTimer);$('#focus-reset').addEventListener('click',resetTimer);
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>5*1024*1024){toast('文件超过 5 MB，请选择自习站 JSON 备份。');return;}try{offerImport(validateBackup(await file.text(),seed));}catch(error){toast(`无法导入：${error.message||'文件格式不正确'}`);}});
window.addEventListener('hashchange',()=>{flushNote();const next=location.hash.slice(1);view=names[next]?next:'today';review=null;render();window.scrollTo({top:0,behavior:'instant'});});window.addEventListener('pagehide',()=>{flushNote();save();});document.addEventListener('visibilitychange',()=>{if(document.hidden){flushNote();save();}else tick();});
function tick(){const now=Date.now();if(!settleExpiredTimer(now))updateTimerUI();if(dayKey()!==lastDay){lastDay=dayKey();flushNote();render();}}
fillIcons();render();tick();setInterval(tick,500);
if(loadError){$('#save-status').textContent=recoveryBlocked?'原数据受保护，当前编辑尚未保存':'原数据已保留，当前为起步示例';$('#save-status').classList.add('warning');toast(recoveryBlocked?'原有数据无法读取且未能另存，已阻止覆盖。请在偏好中下载原始数据或导入有效备份。':'未能读取原有数据，已保留原始副本。可在偏好中下载，或导入有效备份。');}

